        // In buggy, first subtraction with unchecked: 0.5 - 1.5 underflows, causing revert
        bool ok;
        vm.prank(alice);
        try c.CashOut(cashOutAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // In reference, second cashout succeeds (0.5 ether is enough), balances becomes 0
        // In buggy, underflow causes revert, so ok is false
        assertTrue(ok == true, "Second cashout should succeed");
    }
}

